// Fil d'actualité : chaque légendaire tirée devient un post (comme sur un réseau social), avec « J'aime » et commentaires.
export const FEED = { page: 12, commentMax: 200, commentsPerHour: 20, lastShown: 2 };
export const FEED_TABLES = [
  'CREATE TABLE IF NOT EXISTS feed_posts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, card_id BIGINT NOT NULL, ts BIGINT NOT NULL)',
  'CREATE INDEX IF NOT EXISTS feed_posts_user ON feed_posts(user_id, id DESC)',
  'CREATE TABLE IF NOT EXISTS feed_likes (post_id BIGINT NOT NULL, user_id BIGINT NOT NULL, ts BIGINT NOT NULL, PRIMARY KEY (post_id, user_id))',
  'CREATE TABLE IF NOT EXISTS feed_comments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, post_id BIGINT NOT NULL, user_id BIGINT NOT NULL, text TEXT NOT NULL, ts BIGINT NOT NULL)',
  'CREATE INDEX IF NOT EXISTS feed_comments_post ON feed_comments(post_id, id)',
  'ALTER TABLE feed_posts ENABLE ROW LEVEL SECURITY', 'ALTER TABLE feed_likes ENABLE ROW LEVEL SECURITY', 'ALTER TABLE feed_comments ENABLE ROW LEVEL SECURITY',
];

export function installFeed(d) {
  const { route, bad, one, all, run, st, now, ensureGameSchema, notify, cardRows, placeholders, isMaint } = d;
  const person = u => ({ id: u.id, name: u.name, av: u.av ?? null });
  const pid = v => { const n = Math.floor(+v); if (!Number.isFinite(n) || n < 1) bad('Publication inconnue', 404); return n; };

  /** Une publication par carte légendaire tirée (instruction à ajouter au lot d'écritures du paquet). */
  const postStmt = (env, userId, cardId) => st(env, 'INSERT INTO feed_posts (user_id, card_id, ts) VALUES (?,?,?)', userId, cardId, now());

  route('GET', '/api/feed', async ({ env, user, query }) => {
    await ensureGameSchema(env);
    const before = Math.floor(+query.get('before')) || 0;
    const rows = await all(env, `SELECT p.id, p.card_id, p.ts, u.id uid, u.name, u.avatar_v av FROM feed_posts p JOIN users u ON u.id = p.user_id ${before ? 'WHERE p.id < ?' : ''} ORDER BY p.id DESC LIMIT ?`, ...(before ? [before] : []), FEED.page + 1);
    const more = rows.length > FEED.page, page = rows.slice(0, FEED.page);
    if (!page.length) return { posts: [], more: false };
    const ids = page.map(r => +r.id), ph = placeholders(ids.length), cardIds = [...new Set(page.map(r => +r.card_id))];
    const [cards, likes, mine, counts, last] = await Promise.all([
      cardRows(env, cardIds),
      all(env, `SELECT post_id, COUNT(*) n FROM feed_likes WHERE post_id IN (${ph}) GROUP BY post_id`, ...ids),
      all(env, `SELECT post_id FROM feed_likes WHERE user_id = ? AND post_id IN (${ph})`, user.id, ...ids),
      all(env, `SELECT post_id, COUNT(*) n FROM feed_comments WHERE post_id IN (${ph}) GROUP BY post_id`, ...ids),
      all(env, `SELECT * FROM (SELECT c.id, c.post_id, c.text, c.ts, c.user_id, u.name, ROW_NUMBER() OVER (PARTITION BY c.post_id ORDER BY c.id DESC) rn FROM feed_comments c JOIN users u ON u.id = c.user_id WHERE c.post_id IN (${ph})) x WHERE rn <= ? ORDER BY id`, ...ids, FEED.lastShown),
    ]);
    const cardOf = new Map(cards.map(c => [+c.id, c])), likeN = new Map(likes.map(r => [+r.post_id, +r.n])), liked = new Set(mine.map(r => +r.post_id)), countN = new Map(counts.map(r => [+r.post_id, +r.n]));
    return { more, posts: page.map(r => ({ id: +r.id, ts: +r.ts, user: person({ id: r.uid, name: r.name, av: r.av }), card: cardOf.get(+r.card_id) ?? null, likes: likeN.get(+r.id) ?? 0, liked: liked.has(+r.id), comments: countN.get(+r.id) ?? 0,
      last: last.filter(c => +c.post_id === +r.id).map(c => ({ id: +c.id, name: c.name, text: c.text, ts: +c.ts, mine: +c.user_id === +user.id })) })).filter(p => p.card) };
  });

  route('POST', '/api/feed/like', async ({ env, ctx, user, body }) => {
    await ensureGameSchema(env);
    const id = pid(body.post), post = await one(env, 'SELECT p.id, p.user_id, c.title FROM feed_posts p JOIN cards c ON c.id = p.card_id WHERE p.id = ?', id);
    if (!post) bad('Publication inconnue', 404);
    const add = await run(env, 'INSERT INTO feed_likes (post_id, user_id, ts) VALUES (?,?,?) ON CONFLICT DO NOTHING', id, user.id, now());
    let liked = true;
    if (add.meta.changes) { if (+post.user_id !== +user.id) notify(env, ctx, { t: 'notify', msg: `${user.name} aime ta légendaire « ${post.title} »` }, +post.user_id); }
    else { await run(env, 'DELETE FROM feed_likes WHERE post_id = ? AND user_id = ?', id, user.id); liked = false; }
    return { liked, likes: +(await one(env, 'SELECT COUNT(*) n FROM feed_likes WHERE post_id = ?', id)).n };
  });

  route('GET', '/api/feed/:id/comments', async ({ env, user, params }) => {
    await ensureGameSchema(env);
    const id = pid(params.id);
    const rows = await all(env, 'SELECT c.id, c.text, c.ts, c.user_id, u.name FROM feed_comments c JOIN users u ON u.id = c.user_id WHERE c.post_id = ? ORDER BY c.id LIMIT 200', id);
    return { comments: rows.map(c => ({ id: +c.id, name: c.name, text: c.text, ts: +c.ts, mine: +c.user_id === +user.id })) };
  });

  route('POST', '/api/feed/comment', async ({ env, ctx, user, body }) => {
    await ensureGameSchema(env);
    const id = pid(body.post), text = String(body.text ?? '').replace(/\s+/g, ' ').trim().slice(0, FEED.commentMax);
    if (!text) bad('Commentaire vide');
    const post = await one(env, 'SELECT p.id, p.user_id, c.title FROM feed_posts p JOIN cards c ON c.id = p.card_id WHERE p.id = ?', id);
    if (!post) bad('Publication inconnue', 404);
    if (+(await one(env, 'SELECT COUNT(*) n FROM feed_comments WHERE user_id = ? AND ts > ?', user.id, now() - 3600000)).n >= FEED.commentsPerHour) bad('Trop de commentaires : réessaie dans un moment', 429);
    const r = await run(env, 'INSERT INTO feed_comments (post_id, user_id, text, ts) VALUES (?,?,?,?)', id, user.id, text, now());
    if (+post.user_id !== +user.id) notify(env, ctx, { t: 'notify', msg: `${user.name} a commenté ta légendaire « ${post.title} »` }, +post.user_id);
    return { ok: true, comment: { id: r.meta.last_row_id, name: user.name, text, ts: now(), mine: true } };
  });

  route('POST', '/api/feed/comment/delete', async ({ env, user, body }) => {
    await ensureGameSchema(env);
    const c = await one(env, 'SELECT c.id, c.user_id, p.user_id owner FROM feed_comments c JOIN feed_posts p ON p.id = c.post_id WHERE c.id = ?', Math.floor(+body.id) || 0);
    if (!c) bad('Commentaire inconnu', 404);
    if (+c.user_id !== +user.id && +c.owner !== +user.id && !user.is_admin) bad('Tu ne peux supprimer que tes commentaires (ou ceux de ta publication)', 403);
    await run(env, 'DELETE FROM feed_comments WHERE id = ?', c.id);
    return { ok: true };
  });

  return { postStmt };
}
